$pdo->exec("ALTER TABLE warehouse_transfers ADD COLUMN IF NOT EXISTS cancelled_by_name VARCHAR(150) NULL AFTER cancelled_by_id");
$pdo->exec("ALTER TABLE warehouse_transfers ADD COLUMN IF NOT EXISTS cancelled_at DATETIME NULL AFTER cancelled_by_name");
